import{_ as t,o,c,a1 as d}from"./chunks/framework.BKrM4vFX.js";const _=JSON.parse('{"title":"Контейнерный харденинг и graceful shutdown (MS-04)","description":"Контейнерный харденинг и graceful shutdown (MS-04). © 2026 ООО «Аксиома» ИНН:7842223709 · https://github.com/rucorp/mock-services · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services). SPDX-License-Identifier: Apache-2.0 Все три compose-файл","frontmatter":{"sourcePath":"docs/hardening.md"},"headers":[{"level":1,"title":"Контейнерный харденинг и graceful shutdown (MS-04)","slug":"Контейнерный-харденинг-и-graceful-shutdown-ms-04","link":"#Контейнерный-харденинг-и-graceful-shutdown-ms-04","children":[{"level":2,"title":"Флаги","slug":"Флаги","link":"#Флаги","children":[]},{"level":2,"title":"Graceful shutdown","slug":"graceful-shutdown","link":"#graceful-shutdown","children":[]},{"level":2,"title":"Проверки","slug":"Проверки","link":"#Проверки","children":[]},{"level":2,"title":"Порты и bind","slug":"Порты-и-bind","link":"#Порты-и-bind","children":[]},{"level":2,"title":"Лимиты состояния (PD-02)","slug":"Лимиты-состояния-pd-02","link":"#Лимиты-состояния-pd-02","children":[]}]}],"relativePath":"docs/hardening.md","filePath":"docs/hardening.md"}'),a={name:"docs/hardening.md"};function i(l,e,s,r,n,u){return o(),c("div",null,[...e[0]||(e[0]=[d('<p>© 2026 ООО «Аксиома» ИНН:7842223709 · <a href="https://github.com/rucorp/mock-services" target="_blank" rel="noreferrer">https://github.com/rucorp/mock-services</a> · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services). SPDX-License-Identifier: Apache-2.0</p><h1 id="Контейнерный-харденинг-и-graceful-shutdown-ms-04" tabindex="-1">Контейнерный харденинг и graceful shutdown (MS-04) <a class="header-anchor" href="#Контейнерный-харденинг-и-graceful-shutdown-ms-04" aria-label="Permalink to &quot;Контейнерный харденинг и graceful shutdown (MS-04)&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#Контейнерный-харденинг-и-graceful-shutdown-ms-04">Контейнерный харденинг и graceful shutdown (MS-04)</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Флаги">Флаги</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#graceful-shutdown">Graceful shutdown</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Проверки">Проверки</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Порты-и-bind">Порты и bind</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Лимиты-состояния-pd-02">Лимиты состояния (PD-02)</a></li></ul></nav><p>Все три compose-файла задают одинаковый набор харденинг-флагов каждому сервису:</p><ul><li><code>docker-compose.yml</code> — 10 сервисов (весь контур, из исходников)</li><li><code>docker-compose.include.yml</code> — 10 сервисов (включая kontur-ofd-mock)</li><li><code>docker-compose.staging.yml</code> — 2 сервиса (tbank + kassa)</li></ul><h2 id="Флаги" tabindex="-1">Флаги <a class="header-anchor" href="#Флаги" aria-label="Permalink to &quot;Флаги&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Флаг</th><th>Значение</th><th>Зачем</th></tr></thead><tbody><tr><td><code>init</code></td><td><code>true</code></td><td>tini как PID 1: сигналы доходят до Node, зомби не накапливаются</td></tr><tr><td><code>read_only</code></td><td><code>true</code></td><td>rootfs только для чтения: запись — лишь в volume <code>/data</code> и tmpfs <code>/tmp</code></td></tr><tr><td><code>tmpfs</code></td><td><code>[&quot;/tmp&quot;]</code></td><td><code>/tmp</code> в памяти, не требует изменения read-only rootfs</td></tr><tr><td><code>cap_drop</code></td><td><code>[&quot;ALL&quot;]</code></td><td>все Linux capabilities сняты (порты 3100+ непривилегированные)</td></tr><tr><td><code>security_opt</code></td><td><code>[&quot;no-new-privileges:true&quot;]</code></td><td>запрет повышения привилегий</td></tr><tr><td><code>pids_limit</code></td><td><code>256</code></td><td>ограничение числа процессов</td></tr></tbody></table><h2 id="graceful-shutdown" tabindex="-1">Graceful shutdown <a class="header-anchor" href="#graceful-shutdown" aria-label="Permalink to &quot;Graceful shutdown&quot;">​</a></h2><p>По <code>SIGTERM</code>/<code>SIGINT</code> (<code>docker stop</code>, <code>docker compose restart</code>) сервис:</p><ol><li>перестаёт принимать новое,</li><li>синхронно сбрасывает отложенные записи состояния и очереди (окно debounce 150 мс),</li><li>закрывает соединения и выходит с кодом 0.</li></ol><p>Страховочный таймер — 1 с, поэтому остановка не упирается в 10-секундный SIGKILL.</p><p>Хелпер — <code>installGracefulShutdown</code> в <code>packages/core</code>.</p><p>Запуск без compose (<code>node services/&lt;name&gt;-mock/server.js</code>) поведение не меняет.</p><h2 id="Проверки" tabindex="-1">Проверки <a class="header-anchor" href="#Проверки" aria-label="Permalink to &quot;Проверки&quot;">​</a></h2><ul><li><code>npm run test:docker</code> — контейнер с полным набором флагов (<code>docker stop</code> → exit 0 ≤ 2 с, отложенная запись переживает рестарт)</li><li><code>npm run test:tbank</code> и <code>npm run test:kassa</code> — регресс «отложенная запись → сигнал → рестарт с тем же state-файлом»</li><li>CI — шаг «Проверка контейнерного харденинга» для всех трёх compose</li></ul><h2 id="Порты-и-bind" tabindex="-1">Порты и bind <a class="header-anchor" href="#Порты-и-bind" aria-label="Permalink to &quot;Порты и bind&quot;">​</a></h2><ul><li>Root compose по умолчанию слушает только <code>127.0.0.1</code>.</li><li>Для осознанного сетевого доступа задайте bind отдельно: <code>MOCK_TBANK_BIND_IP=0.0.0.0 docker compose up</code></li><li>Не используйте <code>0.0.0.0</code> на публичном хосте без <code>MOCK_OPERATOR_TOKEN</code>/<code>MOCK_ADMIN_TOKEN</code>, firewall и TLS — см. <a href="./../SECURITY">SECURITY</a>.</li></ul><h2 id="Лимиты-состояния-pd-02" tabindex="-1">Лимиты состояния (PD-02) <a class="header-anchor" href="#Лимиты-состояния-pd-02" aria-label="Permalink to &quot;Лимиты состояния (PD-02)&quot;">​</a></h2><p>Все 10 адаптеров и <code>docker-compose.include.yml</code> поддерживают:</p><ul><li><code>MOCK_SANDBOX_MAX_STATE_BYTES</code> — байты JSON одной песочницы (пусто — дефолт 8 МиБ при квоте документов, иначе без лимита)</li><li><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code> — байты JSON всех песочниц одного сервиса, включая <code>default</code> (дефолт 64 МиБ). <code>0</code> выключает лимит.</li></ul><p>Квота per-sandbox ≠ память контейнера: общий бюджет сдерживает суммарный рост, но не заменяет <code>mem_limit: 128m</code> и измерение RSS.</p><p>Превышение глобального бюджета на записи/импорте → HTTP 400 + <code>errorCode</code> + <code>sandbox_state_budget_exceeded</code>, <code>kind: &#39;bytes&#39;</code>, без частичного применения.</p><p>См. <a href="./../packages/core/README#байтовые-квоты-песочниц-pd-02-74">байтовые квоты ядра</a> и env-таблицы сервисов.</p>',23)])])}const p=t(a,[["render",i]]);export{_ as __pageData,p as default};
